typedef struct tsl_slab_ref {
    /* Slab this data lives in. Across a mapping, an index into a slab_region's table of */
    /* slab_entry. */
    uint32_t slab;
    /* Byte offset within the slab. */
    uint32_t offset;
    /* Length in bytes. */
    uint32_t length;
} tsl_slab_ref;

TSL_ASSERT(sizeof(tsl_slab_ref) == 12, "tsl_slab_ref size differs from the Rust definition");
TSL_ASSERT(TSL_ALIGNOF(tsl_slab_ref) == 4, "tsl_slab_ref alignment differs from the Rust definition");
