/*
 * Control block at the head of the shared region, followed by capacity data bytes.
 *
 * head and tail are free-running byte counters, not indices, so full and empty are never
 * ambiguous. Access them atomically: the producer releases head after writing bytes, the
 * consumer acquires head before reading them and releases tail after. They are declared as plain
 * integers so this header stays includable from C and C++ alike; the atomicity is a protocol
 * obligation, not a type.
 *
 * Mirrors `RingControl`.
 */
typedef struct tsl_ring_control {
    /* ABI revision the producer wrote this region with. */
    uint32_t abi_rev;
    /* Must be zero. */
    uint32_t _pad0;
    /* Bytes in the data region. Always a power of two. */
    uint64_t capacity;
    /* Must be zero. Keeps the counters off this line. */
    uint8_t _pad1[112];
    /* Bytes ever written. Producer releases, consumer acquires. */
    uint64_t head;
    /* Must be zero. Keeps the counters off each other's line. */
    uint8_t _pad2[120];
    /* Bytes ever consumed. Consumer releases, producer acquires. */
    uint64_t tail;
    /* Must be zero. */
    uint8_t _pad3[120];
} tsl_ring_control;

